from app.database import save_event
from app.reminders.scheduler import is_reminder_due
from datetime import datetime, timedelta

# Stores events generated by the reminder engine
event_log = []


def log_event(medicine, event_type):
    event = {
        "medicine": medicine["name"],
        "event": event_type,
        "timestamp": datetime.now().isoformat(timespec="seconds"),
    }

    event_log.append(event)

    save_event(event)

    print("\nEvent recorded:", event)


def send_reminder(medicine):
    current_time = datetime.now()

    if is_reminder_due(medicine) and medicine["status"] == "scheduled":
        print("\n========== MEDICATION REMINDER ==========")
        print(f"Medicine: {medicine['name']}")
        print(f"Time: {medicine['time']}")
        print("Please confirm your medication status.")
        print("=========================================")

        medicine["status"] = "delivered"
        medicine["delivered_at"] = current_time

        log_event(medicine, "delivered")

        print("Reminder status:", medicine["status"])


def check_no_response(medicine, timeout=30):
    if medicine["status"] == "delivered":
        elapsed = datetime.now() - medicine["delivered_at"]

        if elapsed >= timedelta(seconds=timeout):
            medicine["status"] = "no_response"

            log_event(medicine, "no_response")

            print(f"\n{medicine['name']}: No response detected.")

            if not medicine.get("escalation_sent", False):
                print("\n========== CAREGIVER ALERT ==========")
                print(f"Medicine: {medicine['name']}")
                print("Patient has not responded.")
                print("Please follow up with the patient.")
                print("=====================================")

                medicine["escalation_sent"] = True


def record_patient_response(medicine, response):
    if medicine["status"] != "delivered":
        print("This reminder cannot accept a response.")
        return

    if response not in ["confirmed", "skipped"]:
        print("Invalid response.")
        return

    medicine["status"] = response

    log_event(medicine, response)

    print(f"\nPatient response recorded: {response}")
